              "metric_contributions": [
                {
                  "metric": "clarity | value_judgment | execution_reliability | calibration | reflection_depth",
                  "direction": "positive | negative",
                  "delta": 0.01-0.30,
                  "title": "string",
                  "reason": "string",
                  "source_type": "daily_entry | thinking_card | quest | verification | principle",
