                    status: principle.status
                )
            },
            extra: extra
        )
    }

    private func basePayload(for promptID: PromptID, context: TodayAIContext) -> [String: String] {
        switch promptID {
        case .organizeCards:
            return [
                "rawText": context.draft.rawText
